const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\r?\n/);
    if (input.length < 2) return;

    const P = input[0].trim();
    const A = input[1].trim();

    const countP = {};
    for (const ch of P) {
        countP[ch] = (countP[ch] || 0) + 1;
    }

    for (const ch of A) {
        if (ch === '*') continue;
        if (!countP[ch] || countP[ch] === 0) {
            console.log('N');
            return;
        }
        countP[ch]--;
    }

    console.log('S');
}

